<template><section data-framework-manager><p>框架只保存产品类型与选配规则；使用时按本次主机查询真实在售销售 SKU。</p><el-button v-if="store.can('product:framework:create')" @click="edit()" data-new-framework>新建选配框架</el-button><article v-for="f in (store.data.benefitFrameworks||[]).filter(f=>!f.deletedAt)" :key="f.id" class="framework-row"><strong>{{ f.name }}</strong><span>修订 {{ f.revision }} · {{ f.status==='available'?'可用':'停用' }} · {{ f.groups.length }} 组选配</span><el-button @click="edit(f)">查看／修改</el-button><el-button v-if="store.can('product:framework:create')" @click="copy(f)">复制框架</el-button><el-button v-if="store.can('product:framework:delete')" @click="remove(f)">删除</el-button></article><el-alert v-if="error" :title="error" type="error" :closable="false" />
<el-dialog v-model="open" title="类型选配框架" width="min(780px,95vw)" :close-on-click-modal="false" :before-close="close" class="framework-dialog" data-framework-dialog :close-on-press-escape="!busy" :show-close="!busy"><el-form label-position="top"><el-form-item label="框架名称"><el-input v-model="draft.name" aria-label="框架名称" :disabled="!canEdit||busy" /></el-form-item><el-form-item label="状态"><el-select v-model="draft.status" aria-label="框架状态" :disabled="!canEdit||busy"><el-option value="available" label="可用"/><el-option value="disabled" label="停用"/></el-select></el-form-item></el-form><p>规则版本：{{kind}}。新位置选配允许类型跨组复用，具体商品仍须明确归组。</p><el-button v-if="kind==='type-v1'&&canEdit" :disabled="busy" @click="upgrade">升级为位置选配框架</el-button><el-alert v-if="!known" title="此框架版本暂不支持执行，原记录保留。" type="warning" :closable="false"/><BenefitRuleEditor v-model="draft.groups" :version2="kind==='type-v2'" :enabled="true" :candidates="[]" type-mode :disabled="!canEdit||busy"/><BenefitGroupRelationsEditor v-if="kind==='type-v2'" :model-value="draft.rules||[]" :groups="draft.groups" :disabled="!canEdit||busy" @update:model-value="draft.rules=$event"/><ul v-if="problems.length" class="framework-problems" role="alert" data-framework-problems><li v-for="problem in problems" :key="problem">{{problem}}</li></ul><el-alert v-if="error" :title="error" type="error" :closable="false"/><template #footer><el-button :disabled="busy" @click="close()">关闭</el-button><el-button v-if="canEdit" :loading="busy" @click="save" data-save-framework>保存框架</el-button></template></el-dialog></section></template>
<script setup lang="ts">
import {computed,ref,onBeforeUnmount} from 'vue'
import {useRoute} from 'vue-router'
import BenefitGroupRelationsEditor from './BenefitGroupRelationsEditor.vue'
import {onBeforeRouteLeave} from 'vue-router'
import {ElMessageBox} from 'element-plus'
import {useCatalogStore} from '../../stores/catalog'
import {cloneBenefit} from '../../domain/benefitPackages'
import {frameworkProblems} from '../../domain/benefitFrameworks'
import type {BenefitFramework} from '../../domain/benefitPackageTypes'
import BenefitRuleEditor from './BenefitRuleEditor.vue'
import {localBenefitRequest} from './benefitPackagePresentation'
const route=useRoute(),store=useCatalogStore(),open=ref(false),busy=ref(false),error=ref(''),original=ref(''),request=ref('')
const empty=():BenefitFramework=>({id:'',kind:'type-v2',rules:[],name:'',status:'available',revision:0,groups:[],createdAt:'',updatedAt:'',creationRequestId:'',creationIntent:'',history:[]}),draft=ref(empty())
const kind=computed(()=>draft.value.kind||draft.value.history.at(-1)?.kind||'type-v1'),known=computed(()=>['type-v1','type-v2'].includes(kind.value)),canEdit=computed(()=>known.value&&store.can(draft.value.id?'product:framework:update':'product:framework:create'))
const problems=computed(()=>frameworkProblems(store.data,draft.value.groups,kind.value,draft.value.rules||[]))
async function upgrade(){try{await ElMessageBox.confirm('升级后允许类型在多个组复用，旧修订及已保存组合保持原文。此次修改保存后才形成新修订。','升级框架',{confirmButtonText:'采用位置选配',cancelButtonText:'取消'})}catch{return}draft.value.kind='type-v2';draft.value.rules=[]}
function edit(f?:BenefitFramework){draft.value=f?cloneBenefit(f):empty();original.value=JSON.stringify(draft.value);request.value=localBenefitRequest('framework');error.value='';open.value=true}
function copy(f:BenefitFramework){edit();draft.value.name=f.name+' 副本';draft.value.groups=cloneBenefit(f.groups);draft.value.kind=f.kind||f.history.at(-1)?.kind||'type-v1';draft.value.rules=cloneBenefit(f.rules||[])}
async function close(done?:()=>void){if(busy.value)return;if(JSON.stringify(draft.value)!==original.value){try{await ElMessageBox.confirm('框架输入尚未保存，确认放弃？','未保存框架',{confirmButtonText:'放弃修改',cancelButtonText:'继续编辑'})}catch{return}}open.value=false;done?.()}
async function save(){if(busy.value||!canEdit.value)return;const actor=store.activeUserId,preview=store.previewUserId,path=route.fullPath,stamp=JSON.stringify(draft.value);busy.value=true;try{const r=await store.saveBenefitFramework({draft:cloneBenefit(draft.value),expectedRevision:draft.value.revision,requestId:request.value},()=>route.fullPath===path&&actor===store.activeUserId&&preview===store.previewUserId&&stamp===JSON.stringify(draft.value));if(r.ok){draft.value=cloneBenefit(store.data.benefitFrameworks!.find(f=>f.id===r.id)!);original.value=JSON.stringify(draft.value);open.value=false;error.value=''}else error.value=r.message||'未保存，输入保留。'}catch(cause){error.value=cause instanceof Error?cause.message:'保存失败，全部输入保留。'}finally{busy.value=false}}
async function remove(f:BenefitFramework){try{await ElMessageBox.confirm(`删除框架「${f.name}」？`,'删除框架')}catch{return}const r=await store.removeBenefitFramework(f.id,f.revision);error.value=r.ok?'':r.message||'未删除'}
onBeforeRouteLeave(async()=>{if(!open.value)return true;await close();return !open.value})
const unload=(e:BeforeUnloadEvent)=>{if(open.value&&JSON.stringify(draft.value)!==original.value){e.preventDefault();e.returnValue=''}};window.addEventListener('beforeunload',unload);onBeforeUnmount(()=>window.removeEventListener('beforeunload',unload))
</script>
<style>.framework-row{display:flex;align-items:center;gap:12px;flex-wrap:wrap;padding:16px 0;border-bottom:1px solid var(--border-default)}.framework-dialog .el-dialog__body{max-height:65vh;overflow:auto}</style>
